27	    public function category(): BelongsTo
28	    {
29	        return $this->belongsTo(Category::class);
30	    }
31	
32	    public function dataSource(): BelongsTo
33	    {
34	        return $this->belongsTo(DataSource::class);
35	    }
36	
37	    public function transitStops(): BelongsToMany
38	    {
39	        return $this->belongsToMany(TransitStop::class, 'poi_transit_stops')
