{{-- POI Detail Popup / Overlay --}}
<div
  x-data="popupState()"
  x-show="selectedPoi != null"
  x-on:poi-selected.window="onPoiSelected($event.detail.poi)"
  x-on:keydown.escape.window="closePopup"
  class="fixed inset-0 z-50 flex items-end sm:items-center justify-center"
  x-cloak
>
  {{-- Backdrop --}}
  <div
    x-show="selectedPoi != null"
    x-transition:enter="transition-opacity duration-200"
    x-transition:leave="transition-opacity duration-150"
    class="absolute inset-0 bg-black/50 backdrop-blur-sm"
    @click="closePopup"
  ></div>

  {{-- Modal: bottom sheet on mobile, centered on desktop --}}
  <div
    x-show="selectedPoi != null"
    x-transition:enter="transition-all duration-300 ease-out"
    x-transition:enter-start="opacity-0 translate-y-8 sm:translate-y-4 sm:scale-95"
    x-transition:enter-end="opacity-100 translate-y-0 sm:scale-100"
    x-transition:leave="transition-all duration-200 ease-in"
    x-transition:leave-start="opacity-100 translate-y-0 sm:scale-100"
    x-transition:leave-end="opacity-0 translate-y-8 sm:translate-y-4 sm:scale-95"
    class="relative w-full sm:max-w-md max-h-[85vh] sm:max-h-[90vh] overflow-y-auto bg-white dark:bg-gray-900 rounded-t-2xl sm:rounded-2xl shadow-2xl border border-gray-200 dark:border-gray-700"
  >
    {{-- Mobile drag handle --}}
    <div class="sm:hidden flex justify-center pt-2 pb-1">
      <div class="w-10 h-1 rounded-full bg-gray-300 dark:bg-gray-600"></div>
    </div>
    {{-- Close Button --}}
    <button
      @click="closePopup"
      class="absolute top-3 right-3 z-10 w-8 h-8 bg-white/80 dark:bg-gray-800/80 backdrop-blur-sm rounded-full flex items-center justify-center text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-200 hover:bg-white dark:hover:bg-gray-700 shadow-sm transition-all"
    >
      <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
        <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"/>
      </svg>
    </button>

    {{-- Photo / Hero --}}
    <div class="w-full h-48 bg-gradient-to-br from-emerald-100 via-teal-100 to-cyan-100 dark:from-emerald-900/50 dark:via-teal-900/30 dark:to-cyan-900/20 flex items-center justify-center relative overflow-hidden">
      <template x-if="selectedPoi.photo_url">
        <img :src="selectedPoi.photo_url" :alt="selectedPoi.name" class="w-full h-full object-cover" />
      </template>
      <template x-if="!selectedPoi.photo_url">
        <span class="text-7xl opacity-60 select-none" x-html="getCategoryIcon(selectedPoi.category?.slug)"></span>
      </template>

      {{-- Category Badge --}}
      <template x-if="selectedPoi.category">
        <div class="absolute top-3 left-3">
          <span class="px-2.5 py-1 text-xs font-semibold rounded-lg bg-white/80 dark:bg-gray-900/80 backdrop-blur-sm text-gray-700 dark:text-gray-300 shadow-sm border border-white/50 dark:border-gray-700/50 flex items-center gap-1.5">
            <span x-html="getCategoryIcon(selectedPoi.category.slug)"></span>
            <span x-text="selectedPoi.category.name"></span>
          </span>
        </div>
      </template>
    </div>

    {{-- Content --}}
    <div class="p-5 space-y-4">
      {{-- Name & Transit Score --}}
      <div class="flex items-start justify-between gap-3">
        <div class="min-w-0">
          <h2 class="text-lg font-bold text-gray-900 dark:text-gray-100 leading-snug" x-text="selectedPoi.name"></h2>
          <p x-show="selectedPoi.address" class="text-xs text-gray-400 dark:text-gray-500 mt-1 truncate" x-text="selectedPoi.address"></p>
        </div>
        <template x-if="selectedPoi.transit_friendliness_score != null">
          <div class="flex-shrink-0 text-center">
            <div
              :class="scoreColor(selectedPoi.transit_friendliness_score)"
              class="w-14 h-14 rounded-xl flex flex-col items-center justify-center shadow-sm"
            >
              <span class="text-lg font-bold leading-none" x-text="selectedPoi.transit_friendliness_score"></span>
              <span class="text-[9px] font-medium mt-0.5 opacity-80">Skor</span>
            </div>
          </div>
        </template>
      </div>

      {{-- Description --}}
      <template x-if="selectedPoi.description">
        <p class="text-sm text-gray-600 dark:text-gray-400 leading-relaxed" x-text="selectedPoi.description"></p>
      </template>

      {{-- Detail Rows --}}
      <div class="space-y-2.5 bg-gray-50 dark:bg-gray-800/50 rounded-xl p-3.5">
        {{-- Operating Hours --}}
        <template x-if="selectedPoi.operating_hours">
          <div class="flex items-center gap-3 text-sm">
            <svg class="w-4 h-4 text-gray-400 dark:text-gray-500 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"/>
            </svg>
            <span class="text-gray-500 dark:text-gray-400 w-20 flex-shrink-0">Jam Buka</span>
            <span class="text-gray-800 dark:text-gray-200 font-medium" x-text="selectedPoi.operating_hours"></span>
          </div>
        </template>

        {{-- Price Range --}}
        <template x-if="selectedPoi.price_range">
          <div class="flex items-center gap-3 text-sm">
            <svg class="w-4 h-4 text-gray-400 dark:text-gray-500 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z"/>
            </svg>
            <span class="text-gray-500 dark:text-gray-400 w-20 flex-shrink-0">Harga</span>
            <span class="text-gray-800 dark:text-gray-200 font-medium" x-text="priceLabel(selectedPoi.price_range)"></span>
          </div>
        </template>

        {{-- Nearest Stop --}}
        <div class="flex items-center gap-3 text-sm">
          <svg class="w-4 h-4 text-gray-400 dark:text-gray-500 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z"/>
          </svg>
          <span class="text-gray-500 dark:text-gray-400 w-20 flex-shrink-0">Halte</span>
          <span class="text-gray-800 dark:text-gray-200 font-medium">
            <template x-if="selectedPoi.nearest_stop">
              <span>
                <span x-text="selectedPoi.nearest_stop.name"></span>
                <span class="text-gray-400 dark:text-gray-500 font-normal">
                  (<span x-text="selectedPoi.nearest_stop.distance_meters"></span> m · <span x-text="selectedPoi.nearest_stop.walking_minutes"></span> mnt jalan)
                </span>
              </span>
            </template>
            <template x-if="!selectedPoi.nearest_stop">
              <span class="text-gray-400 dark:text-gray-500 font-normal">Tidak tersedia</span>
            </template>
          </span>
        </div>

        {{-- Transit Score Detail --}}
        <template x-if="selectedPoi.transit_friendliness_score != null">
          <div class="flex items-center gap-3 text-sm">
            <svg class="w-4 h-4 text-gray-400 dark:text-gray-500 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13 10V3L4 14h7v7l9-11h-7z"/>
            </svg>
            <span class="text-gray-500 dark:text-gray-400 w-20 flex-shrink-0">Transit</span>
            <span class="font-medium" x-text="transitLabel(selectedPoi.transit_friendliness_score)"></span>
          </div>
        </template>

        {{-- Source Data --}}
        <template x-if="selectedPoi.source_type">
          <div class="flex items-center gap-3 text-sm">
            <svg class="w-4 h-4 text-gray-400 dark:text-gray-500 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"/>
            </svg>
            <span class="text-gray-500 dark:text-gray-400 w-20 flex-shrink-0">Sumber</span>
            <span class="text-gray-800 dark:text-gray-200 font-medium" x-text="sourceLabel(selectedPoi.source_type)"></span>
          </div>
        </template>
      </div>

      {{-- Tags --}}
      <template x-if="selectedPoi.tags && selectedPoi.tags.length > 0">
        <div class="flex flex-wrap gap-1.5">
          <template x-for="tag in selectedPoi.tags" :key="tag">
            <span class="px-2.5 py-1 text-xs rounded-full bg-gray-100 dark:bg-gray-800 text-gray-600 dark:text-gray-400 border border-gray-200 dark:border-gray-700">
              <span x-text="tag"></span>
            </span>
          </template>
        </div>
      </template>

      {{-- Add to Itinerary Button --}}
      <button
        @click="addToItinerary(selectedPoi)"
        x-bind:disabled="isAdded(selectedPoi.id)"
        :class="isAdded(selectedPoi.id)
          ? 'bg-gray-200 dark:bg-gray-700 text-gray-400 dark:text-gray-500 cursor-not-allowed'
          : 'bg-emerald-600 hover:bg-emerald-700 active:bg-emerald-800 text-white shadow-md hover:shadow-lg'"
        class="w-full py-3 px-4 rounded-xl font-semibold text-sm transition-all flex items-center justify-center gap-2"
      >
        <svg class="w-4 h-4" :class="isAdded(selectedPoi.id) ? 'text-gray-400' : 'text-white'" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 4v16m8-8H4"/>
        </svg>
        <span x-text="isAdded(selectedPoi.id) ? 'Sudah di Rencana' : '+ Tambahkan ke Rencana Perjalanan'"></span>
      </button>
    </div>
  </div>
</div>

{{-- Alpine Component State --}}
<script>
  document.addEventListener('alpine:init', () => {
    Alpine.data('popupState', () => ({
      selectedPoi: null,

      onPoiSelected(poi) {
        if (!poi.nearest_stop && poi.transit_stops && poi.transit_stops.length > 0) {
          const sorted = [...poi.transit_stops].sort((a, b) =>
            (a.pivot?.distance_meters || Infinity) - (b.pivot?.distance_meters || Infinity)
          );
          const nearest = sorted[0];
          poi.nearest_stop = {
            id: nearest.id,
            name: nearest.name,
            distance_meters: nearest.pivot?.distance_meters || 0,
            walking_minutes: nearest.pivot?.walking_minutes || Math.round((nearest.pivot?.distance_meters || 0) / 80),
          };
        }
        this.selectedPoi = poi;
        document.body.style.overflow = 'hidden';
      },

      closePopup() {
        this.selectedPoi = null;
        document.body.style.overflow = '';
      },

      getCategoryIcon(slug) {
        const icons = {
          'kuliner': '<svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 5v2m0 4v2m0 4v2M5 5a2 2 0 00-2 2v3a2 2 0 110 4v3a2 2 0 002 2h14a2 2 0 002-2v-3a2 2 0 110-4V7a2 2 0 00-2-2H5z"/></svg>',
          'wisata': '<svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4"/></svg>',
          'penginapan': '<svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6"/></svg>',
        };
        return icons[slug] || '<svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M17.657 16.657L13.414 20.9a1.998 1.998 0 01-2.827 0l-4.244-4.243a8 8 0 1111.314 0z"/></svg>';
      },

      scoreColor(score) {
        if (score >= 8) return 'bg-emerald-100 dark:bg-emerald-900/60 text-emerald-700 dark:text-emerald-300';
        if (score >= 7) return 'bg-amber-100 dark:bg-amber-900/60 text-amber-700 dark:text-amber-300';
        return 'bg-red-100 dark:bg-red-900/60 text-red-700 dark:text-red-300';
      },

      priceLabel(range) {
        const map = { low: 'Rendah', medium: 'Sedang', high: 'Tinggi' };
        return map[range] || range || '-';
      },

      transitLabel(score) {
        if (score >= 8) return 'Sangat Mudah Diakses';
        if (score >= 7) return 'Mudah Diakses';
        return 'Kurang Terjangkau';
      },

      sourceLabel(type) {
        const map = {
          'menu_go': 'MenuGO',
          'struk_go': 'StrukGO',
          'property_go': 'PropertyGO',
          'community_activity': 'Aktivitas Komunitas',
          'field_survey': 'Survei Lapangan',
        };
        return map[type] || type || '—';
      },

      addToItinerary(poi) {
        if (this.isAdded(poi.id)) {
          Alpine.store('toasts').info('POI sudah ada di rencana perjalanan');
          return;
        }
        this.$dispatch('add-to-itinerary', { poi });
        this.closePopup();
        Alpine.store('toasts').success(`"${poi.name}" ditambahkan ke rencana`);
      },

      isAdded(poiId) {
        if (!this.$store.itinerary?.items) return false;
        return this.$store.itinerary.items.some(
          item => (item.poi_id || item.poi?.id) === poiId
        );
      },
    }));
  });
</script>

