6	<div id="map" class="w-full" style="height: calc(var(--vh, 1vh) * 100 - 52px);"></div>
7	@endsection
8	
9	@push('scripts')
10	<script>
11	var map, poiCluster, transitRoutesLayer, transitStopsLayer, transitRadiusLayer;
12	
13	function initMap() {
14	    if (map) return;
15	
16	    // Fix mobile viewport height
17	    var vh = window.innerHeight * 0.01;
18	    document.documentElement.style.setProperty('--vh', vh + 'px');
19	    window.addEventListener('resize', function() {
20	        var vh = window.innerHeight * 0.01;
21	        document.documentElement.style.setProperty('--vh', vh + 'px');
22	    });
23	
24	    var isMobile = window.innerWidth < 768;
25	
26	    map = L.map('map', {
27	        center: [-7.805, 110.378],
28	        zoom: isMobile ? 13 : 14,
29	        zoomControl: !isMobile,
30	        attributionControl: !isMobile,
31	    });
32	
33	    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
34	        attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OSM</a> contributors',
35	        maxZoom: 19,
36	    }).addTo(map);
37	
38	    // Mobile: add zoom control in bottom-right
39	    if (isMobile) {
40	        L.control.zoom({ position: 'bottomright' }).addTo(map);
41	    }
42	
43	    // Marker cluster
44	    poiCluster = L.markerClusterGroup({
45	        chunkedLoading: true,
46	        spiderfyOnEveryZoom: true,
47	        maxClusterRadius: isMobile ? 60 : 50,
48	        disableClusteringAtZoom: isMobile ? 15 : 16,
49	    });
50	
51	    // Transit stops layer group (for toggle)
52	    transitStopsLayer = L.layerGroup();
53	    transitRadiusLayer = L.layerGroup();
54	    transitRoutesLayer = L.layerGroup();
55	
56	    loadPois();
57	    loadTransitStops();
58	    loadTransitRoutes();
59	
60	    // Layer control - collapsible on mobile
61	    L.control.layers(null, {
62	        'Rute Transit': transitRoutesLayer,
63	        'Halte': transitStopsLayer,
64	        'Radius 500m': transitRadiusLayer
65	    }, { collapsed: isMobile }).addTo(map);
66	}
67	
68	function loadPois(filters) {
69	    if (!poiCluster) return;
70	    poiCluster.clearLayers();
71	
72	    var url = '/api/v1/pois?per_page=200';
73	    if (filters) url += filters;
74	
75	    fetch(url)
76	        .then(function(res) { return res.json(); })
77	        .then(function(response) {
78	            var pois = response.data || [];
79	            pois.forEach(function(poi) {
80	                var lat = parseFloat(poi.latitude);
81	                var lng = parseFloat(poi.longitude);
82	                if (isNaN(lat) || isNaN(lng)) return;
83	
84	                var iconHtml = poi.photo_url
85	                    ? '<div class="photo-marker" style="background-image:url(' + poi.photo_url + ')"></div>'
86	                    : '<span style="font-size:1.35rem;line-height:1;display:block;text-align:center;filter:drop-shadow(0 1px 2px rgba(0,0,0,0.3))">' + (poi.category?.icon || 'POI') + '</span>';
87	
88	                var marker = L.marker([lat, lng], {
89	                    icon: L.divIcon({
90	                        className: 'poi-marker',
91	                        html: iconHtml,
92	                        iconSize: poi.photo_url ? [40, 40] : [32, 32],
93	                        iconAnchor: poi.photo_url ? [20, 20] : [16, 16],
94	                    }),
95	                });
96	
97	                marker.bindTooltip(poi.name || 'POI', { direction: 'top', offset: [0, -18] });
98	                marker.on('click', function() {
99	                    window.dispatchEvent(new CustomEvent('poi-selected', { detail: poi }));
100	                });
101	
102	                poiCluster.addLayer(marker);
103	            });
104	
105	            if (!map.hasLayer(poiCluster)) map.addLayer(poiCluster);
106	        })
107	        .catch(function(err) {
108	          console.error('Failed to load POIs:', err);
109	          window.dispatchEvent(new CustomEvent('load-error', { detail: { message: err.message || 'Gagal memuat POI' } }));
110	        });
111	}
112	
113	function loadTransitStops() {
114	    fetch('/api/v1/transit-stops')
115	        .then(function(res) { return res.json(); })
116	        .then(function(response) {
117	            var stops = response.data || [];
118	            (Array.isArray(stops) ? stops : []).forEach(function(stop) {
119	                var lat = parseFloat(stop.latitude);
120	                var lng = parseFloat(stop.longitude);
121	                if (isNaN(lat) || isNaN(lng)) return;
122	
123	                // Radius 500m
124	                var radius = L.circle([lat, lng], {
125	                    radius: 500,
126	                    dashArray: '4 8',
127	                    opacity: 0.08,
128	                    fillOpacity: 0.05,
129	                    color: '#1a3a4a',
130	                    fillColor: '#1a3a4a',
131	                    interactive: false,
132	                });
133	                transitRadiusLayer.addLayer(radius);
134	
135	                // Stop dot
136	                var dot = L.circleMarker([lat, lng], {
