3	namespace App\Http\Controllers\Api\V1;
4	
5	use App\Http\Controllers\Controller;
6	use App\Models\Poi;
7	use Illuminate\Http\JsonResponse;
8	use Illuminate\Http\Request;
9	
10	class PoiController extends Controller
11	{
12	    public function index(Request $request): JsonResponse
13	    {
14	        $query = Poi::with('category', 'dataSource', 'transitStops');
15	
16	        if ($category = $request->query('category')) {
17	            $query->whereHas('category', fn($q) => $q->where('slug', $category));
18	        }
19	        if ($priceRange = $request->query('price_range')) {
20	            $query->where('price_range', $priceRange);
21	        }
22	        if ($nearStopId = $request->query('near_stop_id')) {
23	            $maxDistance = $request->query('max_distance', 500);
24	            $query->whereHas('transitStops', fn($q) => $q->where('transit_stop_id', $nearStopId)
25	                ->where('distance_meters', '<=', (int)$maxDistance));
26	        }
27	        $query->when($request->tags, fn($q, $t) => $q->where(function($q) use ($t) {
28	            foreach (explode(',', $t) as $tag) {
29	                $q->whereJsonContains('tags', trim($tag));
30	            }
31	        }));
32	        // Bounding box filter
33	        if ($bbox = $request->query('bbox')) {
34	            [$minLng, $minLat, $maxLng, $maxLat] = explode(',', $bbox);
35	            $query->whereBetween('longitude', [(float)$minLng, (float)$maxLng])
36	                  ->whereBetween('latitude', [(float)$minLat, (float)$maxLat]);
37	        }
38	
39	        $perPage = $request->query('per_page', 50);
40	        $pois = $query->paginate(min((int)$perPage, 200));
41	
42	        // Add nearest_stop for each POI
43	        $pois->through(function ($poi) {
44	            $poi->nearest_stop = $this->getNearestStop($poi);
45	            return $poi;
46	        });
47	
48	        return response()->json([
49	            'success' => true,
50	            'data' => $pois->items(),
51	            'meta' => ['pagination' => [
52	                'page' => $pois->currentPage(),
53	                'per_page' => $pois->perPage(),
54	                'total' => $pois->total(),
55	            ]],
56	        ]);
57	    }
58	
59	    public function show(int $id): JsonResponse
60	    {
61	        $poi = Poi::with(['category', 'dataSource', 'transitStops' => function ($q) {
62	            $q->orderByPivot('distance_meters')->limit(3);
63	        }])->find($id);
64	
65	        if (!$poi) {
66	            return response()->json(['success' => false, 'message' => 'POI tidak ditemukan'], 404);
67	        }
68	
69	        $poi->nearest_stop = $this->getNearestStop($poi);
70	
71	        return response()->json(['success' => true, 'data' => $poi]);
72	    }
73	
74	    private function getNearestStop($poi): ?array
75	    {
76	        $stop = $poi->transitStops->sortBy('pivot.distance_meters')->first();
77	
78	        if (!$stop) {
79	            return null;
80	        }
81	
82	        return [
83	            'id' => $stop->id,
84	            'name' => $stop->name,
85	            'distance_meters' => (int) $stop->pivot->distance_meters,
86	            'walking_minutes' => (int) $stop->pivot->walking_minutes,
87	            'latitude' => (float) $stop->latitude,
88	            'longitude' => (float) $stop->longitude,
89	        ];
90	    }
91	}
