133	            class="md:hidden fixed inset-0 bg-black/30 z-30"
134	            @click="$store.sidebar.closeMobileSheet()"
135	            x-transition:enter="transition-opacity duration-200"
136	            x-transition:leave="transition-opacity duration-150"
137	        ></div>
138	    </div>
139	
140	    <script>
141	    document.addEventListener('alpine:init', () => {
142	        // -- Dark mode --
143	        Alpine.store('dark', {
144	            on: localStorage.getItem('dark-mode') === 'true',
145	            toggle() {
146	                this.on = !this.on;
147	                localStorage.setItem('dark-mode', this.on);
148	                if (this.on) document.documentElement.classList.add('dark');
149	                else document.documentElement.classList.remove('dark');
150	            },
151	            init() {
152	                if (this.on) document.documentElement.classList.add('dark');
153	            }
154	        });
155	
156	        // -- Toast notifications --
157	        Alpine.store('toasts', {
158	            items: [],
159	            nextId: 1,
160	            add(message, type = 'info', duration = 3500) {
161	                const id = this.nextId++;
162	                this.items.push({ id, message, type, show: true });
163	                if (duration > 0) {
164	                    setTimeout(() => this.dismiss(id), duration);
165	                }
166	                return id;
167	            },
168	            dismiss(id) {
169	                const toast = this.items.find(t => t.id === id);
170	                if (toast) toast.show = false;
171	                setTimeout(() => { this.items = this.items.filter(t => t.id !== id); }, 300);
172	            },
173	            success(msg) { return this.add(msg, 'success'); },
174	            error(msg) { return this.add(msg, 'error', 5000); },
175	            info(msg) { return this.add(msg, 'info'); },
176	            warning(msg) { return this.add(msg, 'warning', 4000); },
177	        });
178	
179	        // -- View tab --
180	        Alpine.store('view', {
181	            tab: 'explore',
182	            setTab(t) { this.tab = t; },
183	            async loadInsight() {
184	                this.tab = 'insight';
185	                if (Alpine.store('insight')) return;
186	                try {
187	                    const res = await fetch('/api/v1/insight/area');
188	                    const json = await res.json();
189	                    Alpine.store('insight', json.data);
190	                } catch(e) { console.error('Insight:', e); }
191	            }
192	        });
193	
194	        // -- Mobile sidebar / bottom sheet --
195	        Alpine.store('sidebar', {
196	            isMobileSheet: window.innerWidth < 768,
197	            sheetHeight: 40,
198	            sheetMaxHeight: 80,
199	            touchStartY: 0,
200	            init() {
201	                const resize = () => {
202	                    this.isMobileSheet = window.innerWidth < 768;
203	                };
204	                window.addEventListener('resize', resize);
205	            },
206	            closeMobileSheet() {
207	                if (this.isMobileSheet) this.sheetHeight = 30;
208	            },
209	            onTouchStart(e) {
210	                this.touchStartY = e.touches[0].clientY;
211	            },
212	            onTouchMove(e) {
213	                if (!this.isMobileSheet) return;
214	                const delta = this.touchStartY - e.touches[0].clientY;
215	                if (delta > 50) this.sheetHeight = Math.min(80, this.sheetHeight + 10);
216	                else if (delta < -50) this.sheetHeight = Math.max(30, this.sheetHeight - 10);
217	            }
218	        });
219	
220	        // -- Filters --
221	        Alpine.store('filters', {
222	            categories: [],
223	            priceRange: null,
224	            nearTransit: false,
225	            tags: [],
226	            query: '',
227	            toQueryString() {
228	                const p = [];
229	                if (this.categories.length) p.push('category=' + this.categories[0]);
230	                if (this.priceRange) p.push('price_range=' + this.priceRange);
231	                if (this.tags.length) p.push('tags=' + this.tags.join(','));
232	                if (this.nearTransit) p.push('near_stop_id=all&max_distance=300');
233	                return p.length ? '&' + p.join('&') : '';
234	            }
235	        });
236	
237	        // -- Itinerary --
238	        Alpine.store('itinerary', {
239	            open: false,
240	            title: '',
241	            total_estimated_minutes: null,
242	            ai_narrative: '',
243	            items: [],
244	            data: null,
245	            selectedIds: [],
246	            close() { this.open = false; },
247	            addPoi(id) {
248	                if (!this.selectedIds.includes(id)) this.selectedIds.push(id);
249	            },
250	            removePoi(id) {
251	                this.selectedIds = this.selectedIds.filter(i => i !== id);
252	            },
253	            async build() {
254	                if (!this.selectedIds.length) return;
255	                try {
256	                    const res = await fetch('/api/v1/itineraries', {
257	                        method: 'POST',
258	                        headers: {'Content-Type': 'application/json'},
259	                        body: JSON.stringify({
260	                            session_token: localStorage.getItem('session_token') || ('anon-' + Date.now()),
261	                            poi_ids: this.selectedIds
262	                        })
263	                    });
264	                    const json = await res.json();
265	                    if (json.success) {
266	                        this.title = json.data.title;
267	                        this.total_estimated_minutes = json.data.total_estimated_minutes;
268	                        this.ai_narrative = json.data.ai_narrative;
269	                        this.items = json.data.items;
270	                        this.data = json.data;
271	                        this.open = true;
272	                        Alpine.store('toasts').success('Rencana perjalanan berhasil dibuat!');
273	                    }
274	                } catch(e) {
275	                    console.error('Itinerary build:', e);
276	                    Alpine.store('toasts').error('Gagal membuat rencana perjalanan');
277	                }
278	            }
279	
280	        }); // end itinerary
281	
282	        // end alpine:init
283	    });
284	
285	    function appState() {
286	        return {
287	            selectedPoi: null,
288	            selectedPoiIds: [],
289	            initApp() {
290	                if (!localStorage.getItem('session_token')) {
291	                    localStorage.setItem('session_token', 'anon-' + Date.now());
292	                }
293	                // Listen for poi-selected from sidebar/map (dispatched as { poi })
294	                window.addEventListener('poi-selected', (e) => {
295	                    const poi = e.detail?.poi || e.detail;
296	                    this.selectedPoi = poi;
297	                });
298	                // Listen for add-to-itinerary (dispatched from _popup as { poi })
299	                window.addEventListener('add-to-itinerary', (e) => {
300	                    const poi = e.detail?.poi;
301	                    const id = poi?.id || e.detail?.poiId || e.detail;
302	                    if (id) {
303	                        Alpine.store('itinerary').addPoi(id);
304	                        window.dispatchEvent(new CustomEvent('itinerary-updated'));
305	                    }
306	                });
307	            },
308	            openPopup(p) {
309	                this.selectedPoi = p;
310	                // Reshow popup if already hidden
311	            },
312	            closePopup() {
313	                this.selectedPoi = null;
314	            },
315	            addToItinerary(poiId) {
316	                if (poiId) {
317	                    Alpine.store('itinerary').addPoi(poiId);
318	                    window.dispatchEvent(new CustomEvent('itinerary-updated'));
319	                }
320	                this.closePopup();
321	            }
322	        };
323	    }
324	    </script>
325	    @stack('scripts')
326	</body>
327	</html>
