3	namespace App\Http\Controllers\Api\V1;
4	
5	use App\Http\Controllers\Controller;
6	use App\Models\Poi;
7	use App\Services\AIService;
8	use Illuminate\Http\JsonResponse;
9	use Illuminate\Http\Request;
10	
11	class SearchController extends Controller
12	{
13	    public function __invoke(Request $request): JsonResponse
14	    {
15	        $validated = $request->validate(['query' => 'required|string|max:200']);
16	
17	        $ai = app(AIService::class);
18	        $filters = $ai->parseSearchQuery($validated['query']);
19	
20	        $query = Poi::with('category', 'dataSource', 'transitStops');
21	
22	        if ($category = $filters['category'] ?? null) {
23	            $query->whereHas('category', fn($q) => $q->where('slug', $category));
24	        }
25	        if ($priceRange = $filters['price_range'] ?? null) {
26	            $query->where('price_range', $priceRange);
27	        }
28	        if (!empty($filters['tags'])) {
29	            foreach ($filters['tags'] as $tag) {
30	                $query->whereJsonContains('tags', $tag);
31	            }
32	        }
33	        if ($filters['near_transit'] ?? false) {
34	            $query->whereHas('transitStops', fn($q) => $q->where('distance_meters', '<=', 500));
35	        }
36	
37	        $results = $query->limit(20)->get();
38	
39	        $count = $results->count();
40	        $categoryLabel = $filters['category'] ?? 'wisata';
41	        $summary = "Ditemukan {$count} tempat {$categoryLabel}";
42	        if (!empty($filters['tags'])) $summary .= " dengan " . implode(', ', $filters['tags']);
43	        if ($filters['near_transit'] ?? false) $summary .= " dekat halte transit";
44	        $summary .= ".";
45	
46	        return response()->json([
47	            'success' => true,
48	            'data' => [
49	                'parsed_filters' => $filters,
50	                'results' => $results,
51	                'ai_summary' => $summary,
52	            ],
53	        ]);
54	    }
55	}
