3	namespace App\Services;
4	
5	use Illuminate\Support\Facades\Http;
6	use Illuminate\Support\Facades\Log;
7	
8	class AIService
9	{
10	    protected string $apiKey;
11	    protected string $apiUrl = 'https://api.anthropic.com/v1/messages';
12	
13	    public function __construct()
14	    {
15	        $this->apiKey = config('services.anthropic.api_key', env('ANTHROPIC_API_KEY', ''));
16	    }
17	
18	    public function parseSearchQuery(string $query): array
19	    {
20	        if (empty($this->apiKey)) {
21	            return $this->ruleBasedParse($query);
22	        }
23	
24	        try {
25	            $response = Http::withHeaders([
26	                'x-api-key' => $this->apiKey,
27	                'anthropic-version' => '2023-06-01',
28	                'content-type' => 'application/json',
29	            ])->timeout(15)->post($this->apiUrl, [
30	                'model' => 'claude-3-haiku-20240307',
31	                'max_tokens' => 300,
32	                'system' => 'Parse query wisata Indonesia ke filter JSON. Hanya output JSON tanpa markdown.',
33	                'messages' => [
34	                    ['role' => 'user', 'content' => "Query: \"$query\"\n\nOutput JSON: {\"category\": \"kuliner|wisata|penginapan|null\", \"tags\": [\"string\"], \"price_range\": \"low|medium|high|null\", \"near_transit\": true|false}"]
35	                ]
36	            ]);
37	
38	            if ($response->successful()) {
39	                $text = $response->json('content.0.text', '');
40	                $text = trim(str_replace(['```json', '```', '```'], '', $text));
41	                return json_decode($text, true) ?: $this->ruleBasedParse($query);
42	            }
43	        } catch (\Exception $e) {
44	            Log::warning('AI parseSearchQuery failed, falling back to rule-based', ['error' => $e->getMessage()]);
45	        }
46	
47	        return $this->ruleBasedParse($query);
48	    }
49	
50	    public function generateItineraryNarrative(array $orderedPois): string
51	    {
52	        if (empty($this->apiKey)) {
53	            return $this->ruleBasedNarrative($orderedPois);
54	        }
55	
56	        $poiList = collect($orderedPois)->map(fn($p) => "- {$p['name']} (kategori: {$p['category_name']}, skor transit: {$p['transit_score']})")->implode("\n");
57	
58	        try {
59	            $response = Http::withHeaders([
60	                'x-api-key' => $this->apiKey,
61	                'anthropic-version' => '2023-06-01',
62	                'content-type' => 'application/json',
63	            ])->timeout(20)->post($this->apiUrl, [
64	                'model' => 'claude-3-haiku-20240307',
65	                'max_tokens' => 500,
66	                'system' => 'Buat narasi itinerary perjalanan wisata di Yogyakarta pakai transportasi Trans Jogja. Bahasa Indonesia. Gaya cerita naratif, bukan list.',
67	                'messages' => [
68	                    ['role' => 'user', 'content' => "Susun narasi itinerary dari destinasi berikut:\n$poiList\n\nTulis dalam 2-3 paragraf naratif."]
69	                ]
70	            ]);
71	
72	            if ($response->successful()) {
73	                return $response->json('content.0.text', $this->ruleBasedNarrative($orderedPois));
74	            }
75	        } catch (\Exception $e) {
76	            Log::warning('AI generate narrative failed', ['error' => $e->getMessage()]);
77	        }
78	
79	        return $this->ruleBasedNarrative($orderedPois);
80	    }
81	
82	    public function generateAreaInsight(array $aggregatedData): string
83	    {
84	        if (empty($this->apiKey)) {
85	            return $this->ruleBasedInsight($aggregatedData);
86	        }
87	
88	        try {
89	            $response = Http::withHeaders([
90	                'x-api-key' => $this->apiKey,
91	                'anthropic-version' => '2023-06-01',
92	                'content-type' => 'application/json',
93	            ])->timeout(20)->post($this->apiUrl, [
94	                'model' => 'claude-3-haiku-20240307',
95	                'max_tokens' => 400,
96	                'system' => 'Analisa data kawasan wisata Yogyakarta. Bahasa Indonesia. Output 2-3 paragraf insight.',
97	                'messages' => [
98	                    ['role' => 'user', 'content' => "Data kawasan:\n" . json_encode($aggregatedData, JSON_PRETTY_PRINT) . "\n\nBeri insight singkat tentang aksesibilitas transit dan rekomendasi."]
99	                ]
100	            ]);
101	
102	            if ($response->successful()) {
103	                return $response->json('content.0.text', $this->ruleBasedInsight($aggregatedData));
104	            }
105	        } catch (\Exception $e) {
106	            Log::warning('AI generate insight failed', ['error' => $e->getMessage()]);
107	        }
108	
109	        return $this->ruleBasedInsight($aggregatedData);
110	    }
111	
112	    // --- Fallback rule-based ---
113	    protected function ruleBasedParse(string $query): array
114	    {
115	        $q = strtolower($query);
116	        $filters = ['category' => null, 'tags' => [], 'price_range' => null, 'near_transit' => false];
117	
118	        if (str_contains($q, 'kuliner') || str_contains($q, 'makan') || str_contains($q, 'gudeg') || str_contains($q, 'angkringan')) {
119	            $filters['category'] = 'kuliner';
120	        }
121	        if (str_contains($q, 'wisata') || str_contains($q, 'museum') || str_contains($q, 'sejarah') || str_contains($q, 'taman')) {
122	            $filters['category'] = 'wisata';
123	        }
124	        if (str_contains($q, 'hotel') || str_contains($q, 'penginapan') || str_contains($q, 'homestay')) {
125	            $filters['category'] = 'penginapan';
126	        }
127	        if (str_contains($q, 'murah') || str_contains($q, 'low') || str_contains($q, 'hemat')) {
128	            $filters['price_range'] = 'low';
129	        }
130	        if (str_contains($q, 'halal')) $filters['tags'][] = 'halal';
131	        if (str_contains($q, 'transit') || str_contains($q, 'halte') || str_contains($q, 'bus')) {
132	            $filters['near_transit'] = true;
133	        }
134	
135	        return $filters;
136	    }
137	
138	    protected function ruleBasedNarrative(array $orderedPois): string
139	    {
140	        $names = collect($orderedPois)->pluck('name');
141	        return "Mulai perjalanan dari **{$names->first()}**, lanjut menjelajahi " .
142	               $names->slice(1, -1)->implode(', ') .
143	               ", dan akhiri di **{$names->last()}**. " .
144	               "Setiap lokasi bisa dijangkau dengan Trans Jogja dalam jarak jalan kaki yang nyaman.";
145	    }
146	
147	    protected function ruleBasedInsight(array $data): string
148	    {
149	        $avg = $data['average_transit_friendliness'] ?? 0;
150	        return "Kawasan ini memiliki rata-rata skor transit-friendliness {$avg}. " .
151	               ($avg < 7 ? "Beberapa area perlu prioritas pengembangan akses transit." : "Aksesibilitas transit cukup baik.") .
152	               " Disarankan penambahan halte di area dengan kerapatan POI tinggi namun skor transit rendah.";
153	    }
154	}
